            if I[i][j]!=0 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cell=[]
                while q:
                    y,x=q.popleft(); cell.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and I[ny][nx]!=0:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(cell)
    return out
# verify rule: remove cluster with fewest 9s
def solve(I):
    O=[row[:] for row in I]
    cls=clusters(I)
    cmin=min(cls,key=lambda cl: sum(1 for y,x in cl if I[y][x]==9))
    for y,x in cmin: O[y][x]=0
    return O
